TERMS = [
# ============================ CLOUD & INFRASTRUCTURE ============================
{"term": "Virtualization", "branch": "Cloud & Infrastructure", "de": "Virtualisierung", "tags": ["fundamental"], "wikipedia": "Virtualization",
 "def": "Abstracting physical hardware into multiple isolated virtual instances, so one machine runs many independent operating systems or environments.",
 "context": "The foundation the entire cloud is built on — it's what lets a provider slice one big server among many tenants. The lineage runs hardware virtualization (full VMs) → OS-level virtualization (containers) → functions, each lighter and faster to start than the last.",
 "see_also": ["Hypervisor", "Virtual Machine", "Container", "Cloud Computing"]},

{"term": "Hypervisor", "branch": "Cloud & Infrastructure", "aliases": ["Virtual Machine Monitor", "VMM"],
 "tags": [], "wikipedia": "Hypervisor",
 "def": "The software layer that creates and runs virtual machines, mediating their access to physical hardware. **Type 1** runs on bare metal; **Type 2** runs atop a host OS.",
 "context": "Type 1 (ESXi, Xen, KVM, Hyper-V) is what powers data centres and clouds — minimal overhead, strong isolation. Type 2 (VirtualBox, VMware Workstation) is for desktops. The isolation boundary is a security boundary, so hypervisor escapes are among the most severe vulnerabilities.",
 "see_also": ["Virtualization", "Virtual Machine", "Container", "Bare Metal"]},

{"term": "Virtual Machine", "branch": "Cloud & Infrastructure", "aliases": ["VM"],
 "tags": ["fundamental"], "wikipedia": "Virtual machine",
 "def": "A software emulation of a complete computer, running its own full OS atop a hypervisor, isolated from the host and other VMs.",
 "context": "Strong isolation (each has its own kernel) at the cost of weight — minutes to boot, gigabytes of RAM. The tradeoff against containers is the central infra decision: VMs for hard isolation boundaries, containers for density and speed.",
 "see_also": ["Hypervisor", "Container", "Virtualization", "Guest OS"],
 "confused": [("Container", "A VM virtualises hardware and runs its own kernel (heavy, strong isolation); a container shares the host kernel and isolates only the process (light, weaker isolation).")]},

{"term": "Container", "branch": "Cloud & Infrastructure", "tags": ["fundamental"], "wikipedia": "Containerization (computing)",
 "def": "A lightweight, isolated package bundling an application with its dependencies, sharing the host OS kernel (via namespaces and cgroups) rather than running its own.",
 "context": "Solves 'works on my machine' by shipping the environment with the app. Far lighter than a VM (seconds to start, shared kernel), which is exactly why isolation is weaker — a container escape reaches the host kernel. The unit Kubernetes orchestrates.",
 "see_also": ["Docker", "Kubernetes", "Virtual Machine", "Namespace", "Cgroups", "Image"]},

{"term": "Docker", "branch": "Cloud & Infrastructure", "tags": ["fundamental"], "wikipedia": "Docker (software)",
 "def": "The platform and tooling that popularised containers — building images from a Dockerfile, running them as containers, and sharing them via registries.",
 "context": "Docker didn't invent containers (Linux namespaces/cgroups predate it) but made them usable, standardising the image format (now OCI) and developer workflow. The layered, content-addressed image model is the clever bit — shared base layers, cached builds.",
 "see_also": ["Container", "Image", "Dockerfile", "Kubernetes", "OCI", "Registry"]},

{"term": "Kubernetes", "branch": "Cloud & Infrastructure", "aliases": ["K8s"],
 "tags": ["fundamental", "modern"], "wikipedia": "Kubernetes",
 "def": "An open-source container orchestration platform that automates deploying, scaling, healing, and networking containerised workloads across a cluster.",
 "context": "The de facto standard, built on a declarative, reconciliation-loop model: you describe desired state, controllers continuously drive actual state toward it. Powerful and notoriously complex — often more than a given team needs, which fuels the recurring 'do we really need K8s?' debate.",
 "see_also": ["Container", "Docker", "Pod", "Service Mesh", "Declarative Configuration", "Control Plane"]},

{"term": "IaaS", "branch": "Cloud & Infrastructure", "aliases": ["Infrastructure as a Service"],
 "tags": [], "wikipedia": "Infrastructure as a service",
 "def": "Cloud service model providing raw virtualised infrastructure — compute, storage, networking — that you manage above the hypervisor (EC2, raw VMs).",
 "context": "The bottom of the as-a-Service stack (IaaS → PaaS → SaaS), each layer handing more responsibility to the provider. IaaS gives the most control and the most operational burden; the trend is steadily up the stack toward managed and serverless.",
 "see_also": ["PaaS", "SaaS", "FaaS", "Cloud Computing", "Serverless"]},

{"term": "PaaS", "branch": "Cloud & Infrastructure", "aliases": ["Platform as a Service"],
 "tags": [], "wikipedia": "Platform as a service",
 "def": "Cloud model providing a managed platform — runtime, OS, scaling, deploys — so you ship code without managing servers (Heroku, App Engine, Cloud Run).",
 "context": "The middle layer: less control than IaaS, far less ops. The pitch is 'just push code'; the cost is the platform's constraints and lock-in. Blurs into serverless/FaaS at the lighter end.",
 "see_also": ["IaaS", "SaaS", "FaaS", "Serverless", "Twelve-factor App"]},

{"term": "SaaS", "branch": "Cloud & Infrastructure", "aliases": ["Software as a Service"],
 "tags": ["fundamental"], "wikipedia": "Software as a service",
 "def": "Cloud model delivering finished software over the web on subscription — the provider runs everything; you just use it (Gmail, Salesforce, Slack).",
 "context": "The top of the stack and the dominant commercial software model. From the user's side it's just 'an app in the browser'; the engineering interest is the multi-tenancy underneath — one codebase and infrastructure serving many isolated customers.",
 "see_also": ["IaaS", "PaaS", "Multi-tenancy", "Cloud Computing"]},

{"term": "FaaS", "branch": "Cloud & Infrastructure", "aliases": ["Function as a Service"],
 "tags": ["modern"], "wikipedia": "Function as a service",
 "def": "Cloud model where you deploy individual functions that run on demand, scaling to zero when idle — the core of 'serverless' (AWS Lambda, Cloud Functions).",
 "context": "You pay per invocation and never see a server, but the model has sharp edges: cold starts (latency on the first call), execution time limits, and statelessness force a different architecture. Great for spiky, event-driven, glue workloads; awkward for long-running or latency-critical ones.",
 "see_also": ["Serverless", "PaaS", "Cold Start", "Event-driven Architecture"]},

{"term": "Serverless", "branch": "Cloud & Infrastructure", "tags": ["modern"], "wikipedia": "Serverless computing",
 "def": "An execution model where the provider fully manages server allocation and scaling, including scaling to zero — you reason about code and events, not machines.",
 "context": "There are still servers, of course; you just don't manage or pay for idle ones. Encompasses FaaS plus managed databases, queues, and storage. The tradeoff: minimal ops and pay-per-use vs. cold starts, vendor lock-in, and harder local testing.",
 "see_also": ["FaaS", "PaaS", "Cold Start", "Event-driven Architecture", "Cloud Computing"]},

{"term": "Infrastructure as Code", "branch": "Cloud & Infrastructure", "aliases": ["IaC"],
 "tags": ["fundamental", "modern"], "wikipedia": "Infrastructure as code",
 "def": "Defining and provisioning infrastructure through machine-readable definition files rather than manual setup — infrastructure managed like source code.",
 "context": "The shift that made infrastructure reproducible, reviewable, and version-controlled: no more snowflake servers built by hand and undocumented. Declarative tools (Terraform) describe desired state; the distinction between declarative and imperative IaC is the key design axis.",
 "see_also": ["Terraform", "Declarative Configuration", "GitOps", "Idempotent", "Configuration Management"]},

{"term": "Terraform", "branch": "Cloud & Infrastructure", "tags": ["modern"], "wikipedia": "Terraform (software)",
 "def": "A widely used Infrastructure-as-Code tool that provisions cloud resources declaratively from configuration, tracking real-world resources in a **state file**.",
 "context": "Cloud-agnostic via providers, which is its main appeal over cloud-specific tools. The state file is the crux and the footgun — it's the source of truth that maps config to real resources, and corrupting or losing it is a classic operational disaster (hence remote, locked state).",
 "see_also": ["Infrastructure as Code", "Declarative Configuration", "Idempotent", "State Management"]},

{"term": "Service Mesh", "branch": "Cloud & Infrastructure", "tags": ["modern"], "wikipedia": "Service mesh",
 "def": "A dedicated infrastructure layer handling service-to-service communication — mTLS, retries, load balancing, observability — via sidecar proxies, transparently to the app.",
 "context": "Lifts cross-cutting networking concerns out of application code into the platform (Istio, Linkerd). Powerful for large microservice fleets, but adds real operational complexity and per-hop latency — frequently more than smaller systems need.",
 "see_also": ["Microservices", "Sidecar Pattern", "Kubernetes", "mTLS", "Load Balancer"]},

{"term": "Pod", "branch": "Cloud & Infrastructure", "tags": ["modern"], "wikipedia": "Kubernetes",
 "def": "Kubernetes' smallest deployable unit — one or more tightly-coupled containers sharing network and storage, scheduled together on a node.",
 "context": "Usually one main container per pod; extra ones are sidecars (logging, proxies, mesh). Pods are ephemeral and disposable by design — you don't nurse them, you let controllers (Deployments, ReplicaSets) recreate them, which is the whole cattle-not-pets philosophy.",
 "see_also": ["Kubernetes", "Container", "Sidecar Pattern", "Node", "Deployment"]},

# ============================ DEVOPS & SRE ============================
{"term": "DevOps", "branch": "DevOps & SRE", "tags": ["fundamental"], "wikipedia": "DevOps",
 "def": "A culture and set of practices uniting software development and operations to shorten the delivery cycle through automation, shared ownership, and fast feedback.",
 "context": "Fundamentally cultural before it's tooling — 'you build it, you run it' dissolving the dev-vs-ops wall. The DORA metrics (deploy frequency, lead time, change-fail rate, time-to-restore) are the evidence-based way to measure whether it's actually working.",
 "see_also": ["CI/CD", "SRE", "Infrastructure as Code", "DORA Metrics", "Continuous Delivery"]},

{"term": "CI/CD", "branch": "DevOps & SRE", "aliases": ["Continuous Integration / Continuous Delivery"],
 "tags": ["fundamental"], "wikipedia": "CI/CD",
 "def": "The automated pipeline from code commit to deployment — continuous integration (build + test every change) flowing into continuous delivery/deployment (automated release).",
 "context": "The backbone of modern delivery. Note the CD ambiguity: continuous *delivery* keeps every change deployable with a manual release gate; continuous *deployment* removes even that, shipping to production automatically once tests pass.",
 "see_also": ["CI", "Continuous Delivery", "Build Pipeline", "DevOps", "Deployment"]},

{"term": "Blue-green Deployment", "branch": "DevOps & SRE", "tags": [], "wikipedia": "Blue–green deployment",
 "def": "A release strategy running two identical production environments (blue = current, green = new); you switch traffic to green and can roll back instantly by switching back.",
 "context": "Near-zero-downtime deploys with a fast escape hatch. The cost is double the infrastructure during a release, and database migrations don't switch cleanly (the schema must serve both versions), which is the recurring complication.",
 "see_also": ["Canary Release", "Deployment", "Rollback", "Feature Flag"],
 "confused": [("Canary Release", "Blue-green flips all traffic at once between two full environments; canary shifts a small percentage gradually to catch problems before full rollout.")]},

{"term": "Canary Release", "branch": "DevOps & SRE", "tags": ["modern"], "wikipedia": "Feature toggle",
 "def": "Rolling out a change to a small subset of users first, monitoring it, then gradually expanding if healthy — limiting the blast radius of a bad release.",
 "context": "Named after canaries in coal mines. The progressive, risk-managed counterpart to blue-green's all-at-once flip. Pairs naturally with automated rollback triggered by error/latency metrics, and with feature flags for fine-grained control.",
 "see_also": ["Blue-green Deployment", "Feature Flag", "Observability", "Rollback", "Blast Radius"]},

{"term": "Observability", "branch": "DevOps & SRE", "tags": ["modern"], "wikipedia": "Observability (software)",
 "def": "The ability to understand a system's internal state from its external outputs — built on the three pillars: **metrics**, **logs**, and **traces**.",
 "context": "The distinction from plain monitoring is the point: monitoring watches known failure modes (dashboards, alerts for things you anticipated); observability is about asking *new* questions of a live system to debug the unknown-unknowns inherent in distributed systems.",
 "see_also": ["Metrics", "Logging", "Distributed Tracing", "Monitoring", "Telemetry"],
 "confused": [("Monitoring", "Monitoring answers known questions you set up in advance; observability lets you ask new, unanticipated questions of the running system.")]},

{"term": "SLO", "branch": "DevOps & SRE", "aliases": ["Service Level Objective"],
 "tags": ["modern"], "wikipedia": "Service-level objective",
 "def": "A target value for a reliability metric (an SLI) over a window — e.g. 99.9% of requests succeed within 300ms over 30 days. The internal goal that drives engineering decisions.",
 "context": "The crucial SRE trio: an **SLI** is the measurement, the **SLO** is the target, the **SLA** is the contractual promise (with penalties) — usually set looser than the SLO so you have margin. The SLO defines your **error budget**: the allowed unreliability you can 'spend' on shipping faster.",
 "see_also": ["SLA", "SLI", "Error Budget", "SRE", "Reliability"],
 "confused": [("SLA", "SLI = the metric you measure; SLO = your internal target for it; SLA = the external contract with consequences. Tighten inward: SLA looser than SLO.")]},

{"term": "Error Budget", "branch": "DevOps & SRE", "tags": ["modern"], "wikipedia": "Site reliability engineering",
 "def": "The amount of unreliability an SLO permits (100% minus the target), treated as a budget that can be 'spent' on risk, change, and feature velocity.",
 "context": "The mechanism that turns reliability from a vague aspiration into a shared, quantitative decision: budget remaining → ship boldly; budget exhausted → freeze features and shore up reliability. It aligns dev (wants velocity) and ops (wants stability) on one number instead of arguing.",
 "see_also": ["SLO", "SLA", "SRE", "Toil", "Reliability"]},

{"term": "Toil", "branch": "DevOps & SRE", "tags": ["modern"], "wikipedia": "Site reliability engineering",
 "def": "In SRE, manual, repetitive, automatable operational work that scales linearly with service size and produces no lasting value.",
 "context": "Google's SRE practice caps toil (famously ~50%) so engineers have time to automate it away rather than drowning in it. Naming and measuring toil is what justifies the investment in eliminating it — the alternative is ops work growing forever with the system.",
 "see_also": ["SRE", "Automation", "Postmortem", "Error Budget"]},

{"term": "Postmortem", "branch": "DevOps & SRE", "aliases": ["Incident Retrospective"],
 "tags": ["modern"], "wikipedia": "Postmortem documentation",
 "def": "A written analysis after an incident — timeline, impact, root causes, and corrective actions — ideally **blameless**, focused on systemic fixes rather than fault.",
 "context": "The blameless framing is the load-bearing part: people share what really happened only when they won't be punished for it, and almost every incident has systemic causes (the human 'error' was the last link in a chain of bad defaults). The output is action items that prevent recurrence.",
 "see_also": ["SRE", "Incident Response", "Root Cause Analysis", "Blameless Culture"]},

{"term": "GitOps", "branch": "DevOps & SRE", "tags": ["modern"], "wikipedia": "DevOps",
 "def": "An operational model where a Git repository is the single source of truth for declarative infrastructure and apps, and an agent continuously reconciles the live system to match it.",
 "context": "Extends Infrastructure-as-Code with Git's review, audit, and rollback (revert the commit) as the deployment mechanism. The pull-based reconciliation (Argo CD, Flux) means the cluster converges to the repo state, and drift is detected and corrected automatically.",
 "see_also": ["Infrastructure as Code", "Declarative Configuration", "Kubernetes", "CI/CD", "Reconciliation Loop"]},

{"term": "Twelve-factor App", "branch": "DevOps & SRE", "aliases": ["12-Factor App"],
 "tags": [], "wikipedia": "Twelve-Factor App methodology",
 "def": "A methodology of twelve principles for building cloud-native apps — config in the environment, stateless processes, explicit dependencies, logs as event streams, and so on.",
 "context": "The implicit blueprint behind most PaaS and container platforms. The principles that matter most in practice: strict config/code separation (no secrets in code) and statelessness (so you can scale horizontally and treat instances as disposable).",
 "see_also": ["Stateless", "Configuration Management", "PaaS", "Microservices"]},

# ============================ AI & MACHINE LEARNING ============================
{"term": "Machine Learning", "branch": "AI & Machine Learning", "de": "maschinelles Lernen", "aliases": ["ML"],
 "tags": ["fundamental"], "wikipedia": "Machine learning",
 "def": "Building systems that learn patterns from data to make predictions or decisions, rather than following explicitly programmed rules.",
 "context": "The fundamental inversion from traditional programming: instead of writing rules to produce answers, you feed in examples (data + answers) and the system *infers* the rules. The three broad paradigms — supervised, unsupervised, reinforcement — differ in what signal the data provides.",
 "see_also": ["Supervised Learning", "Neural Network", "Deep Learning", "Training", "Model"]},

{"term": "Neural Network", "branch": "AI & Machine Learning", "de": "neuronales Netz", "aliases": ["Artificial Neural Network", "ANN"],
 "tags": ["fundamental"], "wikipedia": "Neural network (machine learning)",
 "def": "A model of interconnected layers of simple units ('neurons') whose weighted connections are tuned during training — a universal function approximator loosely inspired by biology.",
 "context": "The 'loosely inspired by the brain' framing oversells the biology; mechanically it's stacked matrix multiplications with non-linear activations between them. The non-linearity is essential — without it, any depth collapses to a single linear layer. Depth is what 'deep' learning adds.",
 "see_also": ["Deep Learning", "Backpropagation", "Gradient Descent", "Activation Function", "Weight"]},

{"term": "Deep Learning", "branch": "AI & Machine Learning", "tags": ["fundamental", "modern"], "wikipedia": "Deep learning",
 "def": "Machine learning using neural networks with many layers, which learn hierarchical feature representations directly from raw data.",
 "context": "The breakthrough was eliminating manual feature engineering — the network learns its own features, low-level to high-level, layer by layer. What made it finally work: lots of data, GPU compute, and architectural tricks (ReLU, normalisation, attention). The engine behind the 2010s AI boom.",
 "see_also": ["Neural Network", "Backpropagation", "Transformer", "GPU", "Feature Learning"]},

{"term": "Supervised Learning", "branch": "AI & Machine Learning", "tags": ["fundamental"], "wikipedia": "Supervised learning",
 "def": "Training on **labelled** examples (input → known correct output) so the model learns to map new inputs to outputs — classification (categories) or regression (continuous values).",
 "context": "The most common and best-understood paradigm, but bottlenecked by labels: getting quality labelled data is expensive and often the real project cost. The other paradigms (unsupervised, self-supervised) exist largely to sidestep that bottleneck.",
 "see_also": ["Unsupervised Learning", "Reinforcement Learning", "Classification", "Overfitting", "Training"]},

{"term": "Overfitting", "branch": "AI & Machine Learning", "tags": ["fundamental"], "wikipedia": "Overfitting",
 "def": "When a model learns the training data too well — including its noise — and fails to generalise to new data. Memorisation rather than learning.",
 "context": "The central failure mode of ML. The tell is a wide gap: great on training data, poor on held-out test data. The whole toolkit of regularisation, dropout, cross-validation, and 'more data' exists to fight it. The opposite, underfitting, is a model too simple to capture the real pattern.",
 "see_also": ["Underfitting", "Regularization", "Generalization", "Cross-validation", "Bias-Variance Tradeoff"]},

{"term": "Gradient Descent", "branch": "AI & Machine Learning", "tags": ["fundamental"], "wikipedia": "Gradient descent",
 "def": "The optimisation algorithm that trains most models: iteratively adjust parameters in the direction that most reduces a loss function, step by step downhill.",
 "context": "The engine of nearly all neural-net training. The **learning rate** (step size) is the critical knob — too big and it diverges, too small and it crawls. Variants (SGD, Adam) and the use of mini-batches make it tractable on huge datasets. Backpropagation is just how the gradients get computed.",
 "see_also": ["Backpropagation", "Loss Function", "Learning Rate", "Stochastic Gradient Descent", "Optimization"]},

{"term": "Backpropagation", "branch": "AI & Machine Learning", "aliases": ["Backprop"],
 "tags": ["fundamental"], "wikipedia": "Backpropagation",
 "def": "The algorithm that efficiently computes the gradient of the loss with respect to every weight in a network, by applying the chain rule backward from output to input.",
 "context": "The 1986 insight that made training deep networks feasible — it's the chain rule from calculus applied systematically, reusing intermediate results so the cost is one backward pass rather than perturbing each weight. Gradient descent then uses these gradients to update weights.",
 "see_also": ["Gradient Descent", "Neural Network", "Loss Function", "Chain Rule", "Automatic Differentiation"]},

{"term": "Transformer", "branch": "AI & Machine Learning", "tags": ["fundamental", "modern"], "wikipedia": "Transformer (deep learning architecture)",
 "def": "The neural architecture (2017, 'Attention Is All You Need') built on self-attention, which processes all positions in a sequence in parallel and weighs their relationships.",
 "context": "The architecture behind essentially every modern large language model. Its win over RNNs was twofold: parallel processing (so you can train on massive data fast) and attention's ability to relate distant tokens directly. Scaling it up is what produced GPT and the LLM era.",
 "see_also": ["Attention", "LLM", "Deep Learning", "Token", "Self-attention", "Embedding"]},

{"term": "Attention", "branch": "AI & Machine Learning", "aliases": ["Self-attention"],
 "tags": ["modern"], "wikipedia": "Attention (machine learning)",
 "def": "A mechanism letting a model weigh the relevance of different input elements to each other when producing each output — dynamically focusing on what matters for the current token.",
 "context": "The core innovation of the transformer. Intuitively, for each word it asks 'which other words should I look at to understand this one?' and weights them accordingly. The cost is quadratic in sequence length, which is why long-context efficiency is an active research front.",
 "see_also": ["Transformer", "LLM", "Token", "Context Window", "Embedding"]},

{"term": "Token", "branch": "AI & Machine Learning", "tags": ["modern"], "wikipedia": "Large language model",
 "def": "The unit a language model processes — typically a sub-word chunk (roughly ¾ of a word in English), produced by a tokeniser from raw text.",
 "context": "The model never sees characters or words, only token IDs, which explains a lot of LLM quirks (trouble spelling, counting letters, or doing arithmetic). Tokens are also the unit of pricing and of the context window, so 'how many tokens' is a constant practical concern.",
 "see_also": ["LLM", "Embedding", "Context Window", "Tokenization", "Transformer"]},

{"term": "LLM", "branch": "AI & Machine Learning", "aliases": ["Large Language Model"],
 "tags": ["fundamental", "modern"], "wikipedia": "Large language model",
 "def": "A very large transformer trained on vast text to predict the next token, which yields broad language understanding and generation as an emergent result.",
 "context": "The deceptively simple training objective — predict the next token — scales into apparent reasoning, translation, and coding once the model and data are large enough. Worth holding onto its nature: a powerful statistical model of text, prone to hallucination, not a database of facts or a reasoner in the human sense.",
 "see_also": ["Transformer", "Token", "Hallucination", "Fine-tuning", "RAG", "Prompt Engineering"]},

{"term": "Embedding", "branch": "AI & Machine Learning", "tags": ["modern"], "wikipedia": "Word embedding",
 "def": "A dense vector representation of data (a word, sentence, image) in a high-dimensional space where semantic similarity corresponds to geometric closeness.",
 "context": "The bridge from messy real-world data to numbers a model can work with, and where 'meaning' lives geometrically — the famous king − man + woman ≈ queen. The basis of semantic search and RAG: embed query and documents, retrieve by vector proximity in a vector database.",
 "see_also": ["Vector Database", "RAG", "Token", "Semantic Search", "Cosine Similarity"]},

{"term": "RAG", "branch": "AI & Machine Learning", "aliases": ["Retrieval-Augmented Generation"],
 "tags": ["modern"], "wikipedia": "Retrieval-augmented generation",
 "def": "An LLM technique that retrieves relevant documents (usually by embedding similarity) and feeds them into the prompt as context, so answers are grounded in a specific knowledge base.",
 "context": "The standard remedy for two LLM weaknesses at once: stale training knowledge and hallucination. By grounding generation in retrieved, citable source text, it lets a general model answer over private or current data without retraining. Retrieval quality is usually the bottleneck, not the model.",
 "see_also": ["LLM", "Embedding", "Vector Database", "Hallucination", "Context Window"]},

{"term": "Hallucination", "branch": "AI & Machine Learning", "tags": ["modern"], "wikipedia": "Hallucination (artificial intelligence)",
 "def": "When a generative model produces confident, fluent output that is factually wrong or fabricated — plausible-sounding nonsense.",
 "context": "Not a bug to be fully patched but a consequence of the objective: the model optimises for plausible continuations, not truth, and has no built-in notion of factual grounding. Mitigations (RAG, citations, tool use, verification) reduce it; it can't be assumed gone. The reason to verify LLM output on anything that matters.",
 "see_also": ["LLM", "RAG", "Grounding", "Confabulation"]},

{"term": "Fine-tuning", "branch": "AI & Machine Learning", "tags": ["modern"], "wikipedia": "Fine-tuning (deep learning)",
 "def": "Further training a pre-trained model on a smaller, task- or domain-specific dataset to specialise it, rather than training from scratch.",
 "context": "A form of transfer learning that reuses the expensive general pre-training and adapts cheaply. Efficient variants (LoRA, adapters) tune only a small fraction of parameters. The practical question is usually fine-tuning vs. RAG vs. prompting — fine-tuning changes *behaviour/style*, RAG supplies *knowledge*.",
 "see_also": ["LLM", "Transfer Learning", "Training", "RAG", "LoRA", "Pre-training"],
 "confused": [("RAG", "Fine-tuning bakes new behaviour/style into the weights; RAG injects fresh knowledge at query time without changing the model.")]},

# ============================ GRAPHICS, MEDIA & HCI ============================
{"term": "Pixel", "branch": "Graphics, Media & HCI", "aliases": ["Picture Element"],
 "tags": ["fundamental"], "wikipedia": "Pixel",
 "def": "The smallest addressable element of a raster image or display — a single point, usually carrying colour as RGB (and sometimes alpha) values.",
 "context": "The atom of digital imaging. Worth distinguishing from a device's physical subpixels and from the logical 'CSS pixel', which on high-DPI ('Retina') screens maps to several physical pixels — the device pixel ratio that constantly trips up web layout.",
 "see_also": ["Resolution", "Raster", "Color Space", "Device Pixel Ratio", "Bitmap"]},

{"term": "Resolution", "branch": "Graphics, Media & HCI", "de": "Auflösung", "tags": ["fundamental"], "wikipedia": "Image resolution",
 "def": "The amount of detail in an image or display, given as pixel dimensions (1920×1080) or as a density (DPI/PPI).",
 "context": "Two distinct meanings get conflated: pixel *count* (the grid size) and pixel *density* (how tightly packed, DPI/PPI). Density is what determines sharpness at a given size — the difference between print (300 DPI) and screen (~100 PPI), and why image assets ship at multiple densities.",
 "see_also": ["Pixel", "DPI", "Raster", "Aspect Ratio"]},

{"term": "Vector Graphics", "branch": "Graphics, Media & HCI", "tags": [], "wikipedia": "Vector graphics",
 "def": "Images defined by mathematical shapes — points, lines, curves, polygons — rather than a grid of pixels, so they scale to any size without loss of quality.",
 "context": "The clean contrast with raster: vectors are resolution-independent and tiny for geometric art (logos, icons, fonts, SVG, CAD), but unsuited to photographs. The rule of thumb: vector for designed shapes, raster for captured reality.",
 "see_also": ["Raster", "Pixel", "SVG", "Resolution"],
 "confused": [("Raster", "Raster is a fixed pixel grid (great for photos, blurs when scaled up); vector is math-defined shapes (great for logos/icons, scales infinitely).")]},

{"term": "Codec", "branch": "Graphics, Media & HCI", "aliases": ["Coder-Decoder"],
 "tags": [], "wikipedia": "Codec",
 "def": "An algorithm (and its implementation) that **co**des and **dec**odes a media stream — compressing audio or video for storage/transmission and decompressing it for playback (H.264, AV1, AAC, Opus).",
 "context": "Distinct from a container format (MP4, MKV), which just wraps the codec's output plus metadata and tracks — a common confusion. Codec choice trades compression efficiency against compute and licensing; the royalty-free AV1/Opus vs. patent-encumbered H.264/H.265 split is a live issue.",
 "see_also": ["Lossy Compression", "Container Format", "Bitrate", "Lossless Compression"]},

{"term": "Lossy Compression", "branch": "Graphics, Media & HCI", "tags": [], "wikipedia": "Lossy compression",
 "def": "Compression that permanently discards information judged perceptually unimportant to achieve much smaller files (JPEG, MP3, most video).",
 "context": "Exploits the limits of human perception — frequencies you can't hear, colour detail your eye downplays. The data is gone for good, so re-encoding compounds the loss (generation loss). The right choice when 'good enough and small' beats 'perfect and huge' — i.e. most media delivery.",
 "see_also": ["Lossless Compression", "Codec", "Generation Loss", "Bitrate"],
 "confused": [("Lossless Compression", "Lossy discards data permanently for smaller size (media); lossless reconstructs the original bit-for-bit (text, code, archives).")]},

{"term": "Lossless Compression", "branch": "Graphics, Media & HCI", "tags": [], "wikipedia": "Lossless compression",
 "def": "Compression that reduces size with no loss of information — the original is reconstructed exactly (ZIP, PNG, FLAC, gzip).",
 "context": "Mandatory when every bit matters (executables, text, archives, medical imaging) and bounded by entropy — you can't compress random or already-compressed data further. Works by removing statistical redundancy (repetition, predictable patterns) rather than perceptual detail.",
 "see_also": ["Lossy Compression", "Entropy", "Huffman Coding", "Deflate"]},

{"term": "Rendering", "branch": "Graphics, Media & HCI", "tags": [], "wikipedia": "Rendering (computer graphics)",
 "def": "The process of generating a 2D image from a model or scene description — computing colour for each pixel from geometry, materials, and lighting.",
 "context": "Splits along a hard line: **real-time** rendering (games, ≥60 fps, every trick to fake it fast) vs **offline** rendering (film, hours per frame, physical accuracy). The same word covers rasterisation (fast, approximate) and ray tracing (slow, physically based) — increasingly hybridised in modern GPUs.",
 "see_also": ["Ray Tracing", "Rasterization", "GPU", "Shader", "Frame Rate"]},

{"term": "Ray Tracing", "branch": "Graphics, Media & HCI", "tags": ["modern"], "wikipedia": "Ray tracing (graphics)",
 "def": "A rendering technique that simulates light by tracing the paths of rays through a scene, producing physically accurate reflections, refractions, and shadows.",
 "context": "Long the gold standard for offline/film rendering because it models light realistically; the recent shift is dedicated GPU hardware (RTX) bringing it toward real time, usually hybridised with rasterisation and AI denoising/upscaling to hit playable frame rates.",
 "see_also": ["Rendering", "Rasterization", "GPU", "Global Illumination", "Shader"]},

{"term": "Color Space", "branch": "Graphics, Media & HCI", "aliases": ["Colour Space"],
 "tags": [], "wikipedia": "Color space",
 "def": "A defined model and range (gamut) for representing colour numerically — sRGB, Display P3, Adobe RGB, CMYK for print.",
 "context": "Why the same image looks different across devices, and why colour management exists. sRGB is the safe web default; wide-gamut spaces (P3) show more saturated colours on capable displays. The additive RGB (light/screens) vs subtractive CMYK (ink/print) distinction is the classic gotcha.",
 "see_also": ["Pixel", "Gamut", "RGB", "CMYK", "Color Management"]},

{"term": "Accessibility", "branch": "Graphics, Media & HCI", "de": "Barrierefreiheit", "aliases": ["a11y"],
 "tags": ["fundamental"], "wikipedia": "Computer accessibility",
 "def": "Designing software usable by people with disabilities — visual, motor, auditory, cognitive — via screen-reader support, keyboard navigation, sufficient contrast, captions, and more.",
 "context": "Both an ethical baseline and, increasingly, a legal requirement (EU Accessibility Act, ADA, WCAG conformance levels). Often deferred and expensive to retrofit, cheap to build in. The reliable payoff: accessible design tends to be better, clearer design for everyone (curb-cut effect).",
 "see_also": ["WCAG", "Screen Reader", "Semantic HTML", "Usability"],
 "links": ["[WCAG — Web Content Accessibility Guidelines (W3C)](https://www.w3.org/WAI/standards-guidelines/wcag/)"]},

{"term": "Font", "branch": "Graphics, Media & HCI", "de": "Schriftart", "tags": [], "wikipedia": "Computer font",
 "def": "A digital file defining the shapes (glyphs) of characters at a given style and weight. Modern formats (TrueType, OpenType) describe glyphs as scalable vector outlines.",
 "context": "Technically a **font** is one style/weight and a **typeface** is the whole family, though everyday usage blurs them. OpenType packs in ligatures, alternates, and variable axes (one file morphing weight/width). Web fonts (WOFF2) made typography on the web rich — at a page-weight and privacy cost.",
 "see_also": ["Vector Graphics", "Typography", "OpenType", "Web Font", "Glyph"]},

# ============================ STANDARDS, FORMATS & BODIES ============================
{"term": "RFC", "branch": "Standards, Formats & Bodies", "aliases": ["Request for Comments"],
 "tags": ["fundamental"], "wikipedia": "Request for Comments",
 "def": "A numbered document in the series that defines internet protocols and conventions — HTTP, TCP, IP, SMTP, and the rest of the internet's standards live here.",
 "context": "The primary, authoritative source for how internet protocols actually work — when in doubt, read the RFC. The culture is distinctive: the deliberately humble name ('request for comments'), the running joke of April Fools' RFCs, and 'rough consensus and running code' as the IETF ethos.",
 "see_also": ["IETF", "Internet Standard", "BCP", "Open Standard"]},

{"term": "IETF", "branch": "Standards, Formats & Bodies", "aliases": ["Internet Engineering Task Force"],
 "tags": [], "wikipedia": "Internet Engineering Task Force",
 "def": "The open, volunteer standards body that develops and publishes the internet's core technical standards (as RFCs) — TCP/IP, HTTP, TLS, DNS.",
 "context": "Famously informal and engineering-driven: no formal membership, decisions by 'rough consensus and running code' rather than votes. Its bottom-up, implementation-first culture is a deliberate contrast to the formal, treaty-style process of bodies like the ITU.",
 "see_also": ["RFC", "W3C", "IEEE", "Open Standard", "Internet Standard"]},

{"term": "IEEE", "branch": "Standards, Formats & Bodies", "aliases": ["Institute of Electrical and Electronics Engineers"],
 "tags": [], "wikipedia": "IEEE",
 "def": "A major professional body and standards organisation behind foundational technical standards — Ethernet (802.3), Wi-Fi (802.11), and floating-point arithmetic (754).",
 "context": "Its 802 family standardised the LAN/wireless world you work in daily; IEEE 754 is why floating-point behaves identically across hardware. Also a huge publisher of research. Pronounced 'I-triple-E'.",
 "see_also": ["IEEE 754", "Ethernet", "Wi-Fi", "IETF", "ISO"]},

{"term": "ISO", "branch": "Standards, Formats & Bodies", "aliases": ["International Organization for Standardization"],
 "tags": [], "wikipedia": "International Organization for Standardization",
 "def": "The international standards body publishing standards across virtually every field — including ones you meet constantly: ISO 8601 (dates), ISO/IEC 27001 (infosec management), C and C++ language standards.",
 "context": "Standards by national-body consensus, which is why they're authoritative but slow and (often) paywalled. The name isn't an acronym — it's from Greek *isos*, 'equal', chosen to be the same across languages. ISO/IEC 27001 is likely the one nearest your security work.",
 "see_also": ["ISO 8601", "ISO 27001", "IEC", "Open Standard", "Compliance"]},

{"term": "W3C", "branch": "Standards, Formats & Bodies", "aliases": ["World Wide Web Consortium"],
 "tags": [], "wikipedia": "World Wide Web Consortium",
 "def": "The main standards body for the web — HTML, CSS, the DOM, accessibility (WCAG) — developing 'Recommendations' that browsers implement.",
 "context": "Founded by Tim Berners-Lee. Its slow Recommendation process led the browser makers to spin out faster-moving efforts (WHATWG now owns the living HTML standard, TC39 owns JavaScript), so the web's standards are split across several bodies rather than one.",
 "see_also": ["IETF", "ECMA", "WHATWG", "Open Standard", "HTML"]},

{"term": "ECMA", "branch": "Standards, Formats & Bodies", "aliases": ["Ecma International"],
 "tags": [], "wikipedia": "Ecma International",
 "def": "A standards body best known in software for ECMAScript (ECMA-262) — the standardised core that JavaScript implements — and JSON (ECMA-404).",
 "context": "Why the language is formally 'ECMAScript' and 'JavaScript' is the trademarked common name. The actual yearly evolution (ES2015 onward) runs through TC39, Ecma's technical committee, via a well-defined staged proposal process.",
 "see_also": ["W3C", "TC39", "JavaScript", "JSON", "Open Standard"]},

{"term": "NIST", "branch": "Standards, Formats & Bodies", "aliases": ["National Institute of Standards and Technology"],
 "tags": [], "wikipedia": "National Institute of Standards and Technology",
 "def": "A US agency whose standards carry global weight in computing security — the AES and SHA cryptographic standards, the post-quantum crypto selections, and the Cybersecurity Framework.",
 "context": "The one most entangled with your security work: NIST runs the open competitions that pick worldwide crypto standards (AES, SHA-3, the post-quantum algorithms), and SP 800-series / the CSF are reference points for security programmes well beyond the US government.",
 "see_also": ["AES", "SHA", "Post-Quantum Cryptography", "NIST Cybersecurity Framework", "FIPS"]},

{"term": "Open Standard", "branch": "Standards, Formats & Bodies", "tags": [], "wikipedia": "Open standard",
 "def": "A specification that is publicly available and free (or fairly) to implement, typically developed through an open, consensus process — HTTP, HTML, PDF, TCP/IP.",
 "context": "The bedrock of interoperability and a hedge against lock-in: anyone can build a compatible implementation. The fight is usually at the edges — patent encumbrance, 'open' standards with hostile licensing, and embrace-extend-extinguish tactics that fork a standard into a proprietary dialect.",
 "see_also": ["Interoperability", "RFC", "Reference Implementation", "Vendor Lock-in", "Royalty-free"]},

{"term": "Interoperability", "branch": "Standards, Formats & Bodies", "tags": [], "wikipedia": "Interoperability",
 "def": "The ability of different systems or implementations to work together by adhering to shared standards and formats.",
 "context": "The whole payoff of standards, and harder than it sounds: a spec with ambiguities or optional features yields implementations that nominally conform yet don't interoperate. Conformance test suites and reference implementations exist to close that gap.",
 "see_also": ["Open Standard", "Reference Implementation", "Backward Compatibility", "Conformance"]},

{"term": "Backward Compatibility", "branch": "Standards, Formats & Bodies", "de": "Abwärtskompatibilität", "tags": [],
 "wikipedia": "Backward compatibility",
 "def": "The property that newer versions of a system, format, or interface continue to work with inputs, data, or clients built for older versions.",
 "context": "The constraint that quietly shapes long-lived systems — it's why x86 still carries 1970s baggage and the web never breaks old pages ('don't break userspace', as Linus puts it). The discipline that builds trust and the burden that accretes cruft; SemVer exists precisely to signal when it's broken.",
 "see_also": ["Forward Compatibility", "Semantic Versioning", "API", "Deprecation", "Interoperability"]},
]
